-- ============================================================
-- 0007_sandbox_atomic_trades.sql
-- ============================================================
-- Atomic RPCs for opening/closing sandbox positions.
--
-- Why: src/lib/sandbox/db.ts previously read sandbox_accounts.cash_balance,
-- computed a new balance in application code, then wrote it back in a
-- separate statement (a classic read-then-write race). Two trades submitted
-- close together (double-click, two tabs) could both read the same stale
-- balance, both pass the "sufficient funds" check, and both write — letting
-- a user spend more simulated cash than they have, or double-close the same
-- position and get credited twice. Low real-world severity (simulated
-- money), but a genuine correctness bug worth closing.
--
-- Fix: move the balance mutation into a single Postgres statement per
-- operation (UPDATE ... WHERE cash_balance >= cost / WHERE closed_at IS
-- NULL, both RETURNING the new state), wrapped in a plpgsql function so the
-- position row, trade log row, and cash balance all commit in one
-- transaction. The P&L math itself stays in TypeScript (src/lib/pricing.ts,
-- src/lib/sandbox/db.ts) as the single source of truth — these functions
-- only take already-computed numbers and apply them atomically, so there's
-- no duplicated pricing logic to drift out of sync in SQL.
--
-- Deliberately SECURITY INVOKER (the default — not specified below): these
-- functions run with the calling user's own permissions, so the existing
-- RLS policies from 0004_sandbox.sql ("owner can insert/update own rows")
-- still apply and still do the real access control. p_user_id is compared
-- against auth.uid() as a belt-and-suspenders check, not the primary guard.
--
-- Run this in the Supabase SQL Editor after 0001-0006, same as every prior
-- migration in this directory. src/lib/sandbox/db.ts calls these by name
-- (supabase.rpc("sandbox_open_position" / "sandbox_close_position")) — the
-- app will error on every trade until this has been run.

create or replace function public.sandbox_open_position(
  p_user_id    uuid,
  p_symbol     text,
  p_asset_type text,
  p_side       text,
  p_qty        integer,
  p_fill_price numeric,
  p_cost       numeric,
  p_strike     numeric default null,
  p_expiry     date default null
) returns table (position_id uuid, cash_balance numeric)
language plpgsql
as $$
declare
  v_position_id uuid;
  v_new_balance numeric;
begin
  if p_user_id is distinct from auth.uid() then
    raise exception 'not_authorized';
  end if;

  -- Lazily create the account row (mirrors the old getOrCreateAccount()),
  -- harmless if it already exists.
  insert into public.sandbox_accounts (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  -- The atomic part: read-and-check-and-debit in one statement. If another
  -- concurrent request already spent this user down below p_cost, this
  -- WHERE clause matches zero rows and v_new_balance stays null below —
  -- there's no window between "check balance" and "write balance" for a
  -- second request to land in.
  update public.sandbox_accounts
  set cash_balance = cash_balance - p_cost,
      updated_at = now()
  where user_id = p_user_id
    and cash_balance >= p_cost
  returning cash_balance into v_new_balance;

  if v_new_balance is null then
    raise exception 'insufficient_funds';
  end if;

  insert into public.sandbox_positions
    (user_id, symbol, asset_type, side, qty, avg_cost, strike, expiry)
  values
    (p_user_id, p_symbol, p_asset_type, p_side, p_qty, p_fill_price, p_strike, p_expiry)
  returning id into v_position_id;

  insert into public.sandbox_trades
    (user_id, symbol, asset_type, direction, qty, fill_price, strike, expiry)
  values
    (p_user_id, p_symbol, p_asset_type,
     case when p_side = 'long' then 'buy' else 'sell' end,
     p_qty, p_fill_price, p_strike, p_expiry);

  return query select v_position_id, v_new_balance;
end;
$$;

grant execute on function public.sandbox_open_position(
  uuid, text, text, text, integer, numeric, numeric, numeric, date
) to authenticated;

create or replace function public.sandbox_close_position(
  p_user_id      uuid,
  p_position_id  uuid,
  p_close_price  numeric,
  p_realized_pnl numeric,
  p_cash_delta   numeric
) returns table (cash_balance numeric)
language plpgsql
as $$
declare
  v_position public.sandbox_positions%rowtype;
  v_new_balance numeric;
begin
  if p_user_id is distinct from auth.uid() then
    raise exception 'not_authorized';
  end if;

  -- WHERE closed_at IS NULL is the atomic guard against double-close: if
  -- two concurrent requests race to close the same position, only the first
  -- UPDATE actually matches a row. The second matches zero rows, so
  -- `if not found` below fires for it instead of crediting cash twice.
  update public.sandbox_positions
  set closed_at = now(),
      close_price = p_close_price,
      realized_pnl = p_realized_pnl
  where id = p_position_id
    and user_id = p_user_id
    and closed_at is null
  returning * into v_position;

  if not found then
    raise exception 'position_not_found';
  end if;

  insert into public.sandbox_trades
    (user_id, symbol, asset_type, direction, qty, fill_price, strike, expiry)
  values
    (p_user_id, v_position.symbol, v_position.asset_type,
     case when v_position.side = 'long' then 'sell' else 'buy' end,
     v_position.qty, p_close_price, v_position.strike, v_position.expiry);

  update public.sandbox_accounts
  set cash_balance = cash_balance + p_cash_delta,
      updated_at = now()
  where user_id = p_user_id
  returning cash_balance into v_new_balance;

  return query select v_new_balance;
end;
$$;

grant execute on function public.sandbox_close_position(
  uuid, uuid, numeric, numeric, numeric
) to authenticated;

-- ============================================================
-- 0008_separate_ai_quota_from_hints.sql
-- ============================================================
-- Separates the general AI-action daily budget from the hint daily cap, and
-- makes both atomic.
--
-- Bug: src/lib/ai/quota.ts's consumeAiQuota() (used by chat, explain,
-- review, practice, sandbox-insight, sandbox-trade-idea — cap 25/day) and
-- src/app/api/ai/hint/route.ts's consumeHintQuota() (cap 20/day) both read
-- and write the SAME public.hint_usage row per user, keyed only by user_id
-- with no feature column. Two independently-named, independently-capped
-- budgets were accidentally sharing one counter — heavy hint use eats into
-- (and can block) unrelated AI features and vice versa, in a way that
-- depends on which cap happens to get checked first. quota.ts's own comment
-- describes the general budget as covering "tutor chat, code review,
-- explain-this, practice generation" — hints were never meant to be part of
-- that pool.
--
-- Fix: a dedicated public.ai_usage table for the general budget (same shape
-- as hint_usage, which keeps its original hint-only job), plus one atomic
-- upsert-with-cap function per table so the check-then-increment can't race
-- either (same class of bug as 0007_sandbox_atomic_trades.sql — two
-- concurrent requests reading the same pre-increment count and both being
-- allowed through). The `RETURNING ... WHERE` combination below is what
-- makes it atomic: a request that would exceed the cap simply returns no
-- row (Postgres skips ON CONFLICT DO UPDATE rows whose WHERE is false and
-- excludes them from RETURNING), so "did I get incremented" and "am I under
-- the cap" collapse into a single statement instead of a separate
-- read-then-decide-then-write.
--
-- Run this in the Supabase SQL Editor after 0001-0007. src/lib/ai/quota.ts
-- and src/app/api/ai/hint/route.ts call these RPCs by name — both AI
-- surfaces will error until this has been run.

create table if not exists public.ai_usage (
  user_id uuid primary key references auth.users (id) on delete cascade,
  day     date not null default current_date,
  count   integer not null default 0
);

alter table public.ai_usage enable row level security;

drop policy if exists "AI usage viewable by owner" on public.ai_usage;
create policy "AI usage viewable by owner"
  on public.ai_usage for select
  using (auth.uid() = user_id);

drop policy if exists "Users insert own AI usage" on public.ai_usage;
create policy "Users insert own AI usage"
  on public.ai_usage for insert
  with check (auth.uid() = user_id);

drop policy if exists "Users update own AI usage" on public.ai_usage;
create policy "Users update own AI usage"
  on public.ai_usage for update
  using (auth.uid() = user_id);

-- ─── Atomic "consume if under cap" for the general AI budget ──────────────
-- p_cost varies by feature (see AI_COST in src/lib/ai/quota.ts).
create or replace function public.consume_ai_quota(
  p_user_id uuid,
  p_cost    integer,
  p_cap     integer
) returns table (new_count integer, allowed boolean)
language plpgsql
as $$
declare
  v_count integer;
begin
  if p_user_id is distinct from auth.uid() then
    raise exception 'not_authorized';
  end if;

  insert into public.ai_usage (user_id, day, count)
  values (p_user_id, current_date, p_cost)
  on conflict (user_id) do update
  set count = case when ai_usage.day <> current_date then p_cost else ai_usage.count + p_cost end,
      day = current_date
  where ai_usage.day <> current_date or ai_usage.count + p_cost <= p_cap
  returning ai_usage.count into v_count;

  if v_count is null then
    select au.count into v_count from public.ai_usage au where au.user_id = p_user_id;
    return query select v_count, false;
  else
    return query select v_count, true;
  end if;
end;
$$;

grant execute on function public.consume_ai_quota(uuid, integer, integer) to authenticated;

-- ─── Atomic "consume if under cap" for hints (always cost 1) ──────────────
create or replace function public.consume_hint_quota(
  p_user_id uuid,
  p_cap     integer
) returns table (new_count integer, allowed boolean)
language plpgsql
as $$
declare
  v_count integer;
begin
  if p_user_id is distinct from auth.uid() then
    raise exception 'not_authorized';
  end if;

  insert into public.hint_usage (user_id, day, count)
  values (p_user_id, current_date, 1)
  on conflict (user_id) do update
  set count = case when hint_usage.day <> current_date then 1 else hint_usage.count + 1 end,
      day = current_date
  where hint_usage.day <> current_date or hint_usage.count < p_cap
  returning hint_usage.count into v_count;

  if v_count is null then
    select hu.count into v_count from public.hint_usage hu where hu.user_id = p_user_id;
    return query select v_count, false;
  else
    return query select v_count, true;
  end if;
end;
$$;

grant execute on function public.consume_hint_quota(uuid, integer) to authenticated;

-- ============================================================
-- 0009_signup_source.sql
-- ============================================================
-- Track where a signup came from (?src=reddit, ?src=aops, ?src=discord, etc.)
-- so growth posts can be measured instead of guessed at.

alter table public.profiles add column if not exists signup_source text;

-- Re-create the new-user trigger to also capture signup_source from
-- raw_user_meta_data (set by the client at signup time). OAuth signups
-- don't carry this metadata — those get backfilled by the auth callback
-- route from a short-lived cookie instead.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, display_name, signup_source)
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data ->> 'display_name',
      new.raw_user_meta_data ->> 'full_name'
    ),
    new.raw_user_meta_data ->> 'signup_source'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

-- ============================================================
-- 0010_classes.sql
-- ============================================================
-- Classes: lets a teacher roster students and see aggregate progress.
-- MVP slice of the "Teacher dashboard (School plan)" roadmap item
-- (Q4 2026, see src/app/roadmap/page.tsx) — roster + progress only, no
-- assignments/grading yet. Not gated behind a plan check yet since there's
-- no School-plan Stripe price to check against (see src/lib/stripe.ts);
-- add that gate once one exists, matching the "don't gate what isn't
-- actually sold yet" pattern from earlier oversell-copy fixes.

create table if not exists public.classes (
  id          uuid primary key default gen_random_uuid(),
  teacher_id  uuid not null references auth.users (id) on delete cascade,
  name        text not null,
  join_code   text not null unique,
  created_at  timestamptz not null default now()
);

create table if not exists public.class_members (
  class_id    uuid not null references public.classes (id) on delete cascade,
  student_id  uuid not null references auth.users (id) on delete cascade,
  joined_at   timestamptz not null default now(),
  primary key (class_id, student_id)
);

alter table public.classes enable row level security;
alter table public.class_members enable row level security;

-- Teachers fully manage classes they created.
drop policy if exists "Teachers manage own classes" on public.classes;
create policy "Teachers manage own classes"
  on public.classes for all
  using (auth.uid() = teacher_id)
  with check (auth.uid() = teacher_id);

-- A student who has joined a class can read its name (e.g. "You're in:
-- Ms. Lee's 3rd period"). Does NOT expose join_code to other members —
-- select only, and join_code is never rendered client-side for non-owners.
drop policy if exists "Members can view their class" on public.classes;
create policy "Members can view their class"
  on public.classes for select
  using (
    exists (
      select 1 from public.class_members cm
      where cm.class_id = classes.id and cm.student_id = auth.uid()
    )
  );

-- Teachers can see the roster of their own class.
drop policy if exists "Teachers view own class roster" on public.class_members;
create policy "Teachers view own class roster"
  on public.class_members for select
  using (
    exists (
      select 1 from public.classes c
      where c.id = class_members.class_id and c.teacher_id = auth.uid()
    )
  );

-- A student can see and create their own membership row (joining is
-- self-service via a join code, resolved to a class_id server-side —
-- see src/app/api/classes/join/route.ts).
drop policy if exists "Students view own membership" on public.class_members;
create policy "Students view own membership"
  on public.class_members for select
  using (auth.uid() = student_id);

drop policy if exists "Students join via own row" on public.class_members;
create policy "Students join via own row"
  on public.class_members for insert
  with check (auth.uid() = student_id);

-- ============================================================
-- 0011_assignments.sql
-- ============================================================
-- Assignments: lets a teacher assign specific lessons to a class and track
-- per-student completion against them (not just aggregate track/lesson
-- counts — see supabase/migrations/0010_classes.sql). MVP slice of the
-- Q4 2026 "Assignment grading" roadmap item (src/app/roadmap/page.tsx).
--
-- One row per (class, lesson) — a "3-lesson assignment" is 3 rows created
-- in one teacher action, not a separate parent/junction table. lesson_id is
-- free text, not a foreign key: lessons live in src/lib/tracks.ts as static
-- data, not a DB table (same convention as progress.completed and
-- certificates.track_id).
--
-- Completion is computed on read as a pure intersection of a student's
-- progress.completed lesson-id array against an assignment's lesson_id
-- (see isAssignmentComplete in src/lib/classes.ts) — no completion
-- timestamp is stored here or anywhere else yet. Due dates and on-time/late
-- grading are a deliberate fast-follow, not v1: they need a per-lesson
-- completion timestamp that progress.completed doesn't have today, and
-- adding one is a breaking-ish change to ProgressPayload/mergeProgress and
-- every reader of `completed` (roster, certificates, achievements,
-- useProgress) — not something to bolt on as a side effect of this table.
create table if not exists public.assignments (
  id          uuid primary key default gen_random_uuid(),
  class_id    uuid not null references public.classes (id) on delete cascade,
  lesson_id   text not null,
  created_at  timestamptz not null default now(),
  unique (class_id, lesson_id)
);

alter table public.assignments enable row level security;

-- Teachers fully manage assignments for classes they own. Assignments
-- doesn't carry teacher_id directly, so this joins through classes the
-- same way "Teachers view own class roster" does on class_members.
drop policy if exists "Teachers manage own class assignments" on public.assignments;
create policy "Teachers manage own class assignments"
  on public.assignments for all
  using (
    exists (
      select 1 from public.classes c
      where c.id = assignments.class_id and c.teacher_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.classes c
      where c.id = assignments.class_id and c.teacher_id = auth.uid()
    )
  );

-- A student who has joined the class can see which lessons are assigned.
-- No v1 UI reads this as a student yet, but it costs nothing now and keeps
-- the door open for a student-facing "my assignments" view later without a
-- second migration.
drop policy if exists "Members can view class assignments" on public.assignments;
create policy "Members can view class assignments"
  on public.assignments for select
  using (
    exists (
      select 1 from public.class_members cm
      where cm.class_id = assignments.class_id and cm.student_id = auth.uid()
    )
  );

-- ============================================================
-- 0012_cohort_launch.sql
-- ============================================================
-- Cohort launch foundation for the fixed six-week Quant Foundations Lab.
-- Existing classes and manual assignments remain valid: every new column is
-- nullable, and a class is considered a cohort only after template_id is set.

alter table public.classes
  add column if not exists template_id text,
  add column if not exists starts_on date,
  add column if not exists timezone text,
  add column if not exists launched_at timestamptz;

alter table public.assignments
  add column if not exists week_number smallint,
  add column if not exists position smallint,
  add column if not exists due_on date;

-- Dropped first so this file can be run again (the checks have no IF NOT EXISTS).
alter table public.assignments
  drop constraint if exists assignments_week_number_check,
  drop constraint if exists assignments_position_check;

alter table public.assignments
  add constraint assignments_week_number_check
    check (week_number is null or week_number between 1 and 6),
  add constraint assignments_position_check
    check (position is null or position > 0);

create index if not exists assignments_class_schedule_idx
  on public.assignments (class_id, week_number, position);

-- Launching touches both the class metadata and every scheduled assignment.
-- Keeping those writes inside one Postgres function prevents a failed request
-- from leaving behind a class marked as launched with only part of its plan.
-- Re-launch is intentionally idempotent and updates the fixed schedule.
create or replace function public.launch_cohort(
  p_class_id uuid,
  p_template_id text,
  p_starts_on date,
  p_timezone text,
  p_schedule jsonb
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.classes c
    where c.id = p_class_id and c.teacher_id = auth.uid()
  ) then
    raise exception 'class_not_found' using errcode = 'P0002';
  end if;

  if p_template_id <> 'quant-foundations-v1' then
    raise exception 'unknown_template' using errcode = '22023';
  end if;

  if p_starts_on is null or nullif(btrim(p_timezone), '') is null then
    raise exception 'invalid_cohort_metadata' using errcode = '22023';
  end if;

  if jsonb_typeof(p_schedule) <> 'array' or jsonb_array_length(p_schedule) = 0 then
    raise exception 'invalid_schedule' using errcode = '22023';
  end if;

  update public.classes
  set template_id = p_template_id,
      starts_on = p_starts_on,
      timezone = p_timezone,
      launched_at = now()
  where id = p_class_id and teacher_id = auth.uid();

  insert into public.assignments (
    class_id,
    lesson_id,
    week_number,
    position,
    due_on
  )
  select
    p_class_id,
    item.lesson_id,
    item.week_number,
    item.position,
    item.due_on
  from jsonb_to_recordset(p_schedule) as item(
    lesson_id text,
    week_number smallint,
    position smallint,
    due_on date
  )
  on conflict (class_id, lesson_id) do update
  set week_number = excluded.week_number,
      position = excluded.position,
      due_on = excluded.due_on;
end;
$$;

revoke all on function public.launch_cohort(uuid, text, date, text, jsonb) from public;
grant execute on function public.launch_cohort(uuid, text, date, text, jsonb) to authenticated;

-- ============================================================
-- 0013_progress_timezone.sql
-- ============================================================
-- Learner's IANA timezone (e.g. "America/Chicago"), so server-side readers
-- (the progress API today, reminder emails next) can judge streaks and
-- "active today" on the learner's local calendar day, matching the client.
-- Nullable: rows without it fall back to UTC. Written by a separate
-- best-effort update, so progress sync keeps working before this runs.

alter table public.progress
  add column if not exists timezone text;

alter table public.progress
  drop constraint if exists progress_timezone_length_check;

alter table public.progress
  add constraint progress_timezone_length_check
    check (timezone is null or char_length(timezone) between 1 and 64);

-- ============================================================
-- 0014_session_completions.sql
-- ============================================================
-- Bite-sized lesson sessions (/learn/[sessionId]): one row per learner per
-- session, recording the FIRST completion. Re-runs are tracked by analytics
-- events, not here, so accuracy/duration describe the learner's first pass.
-- Written best-effort by the client, so the app keeps working (local-only)
-- before this runs.

create table if not exists public.session_completions (
  user_id      uuid not null references auth.users (id) on delete cascade,
  session_id   text not null check (char_length(session_id) between 1 and 64),
  completed_at timestamptz not null default now(),
  accuracy     real not null check (accuracy >= 0 and accuracy <= 1),
  duration_ms  integer not null check (duration_ms >= 0),
  primary key (user_id, session_id)
);

alter table public.session_completions enable row level security;

drop policy if exists "Users read own session completions" on public.session_completions;
create policy "Users read own session completions"
  on public.session_completions for select
  using (auth.uid() = user_id);

drop policy if exists "Users insert own session completions" on public.session_completions;
create policy "Users insert own session completions"
  on public.session_completions for insert
  with check (auth.uid() = user_id);

create index if not exists session_completions_completed_at_idx
  on public.session_completions (completed_at);

-- ============================================================
-- 0015_fix_class_rls_recursion.sql
-- ============================================================
-- Fix: the class policies from 0010/0011 query each other, which Postgres
-- rejects with "infinite recursion detected in policy" on EVERY signed-in
-- read of classes, class_members or assignments:
--   classes."Members can view their class"      -> selects class_members
--   class_members."Teachers view own class roster" -> selects classes -> ...
-- That breaks session-bound reads such as GET /api/classes, /api/classes/joined
-- and requireTeacherOwnsClass (caught by supabase/testing, PGlite-backed).
--
-- The membership checks move into SECURITY DEFINER helpers. They run as the
-- table owner, so their lookups skip RLS and can't recurse, and they only
-- ever answer about the caller (auth.uid()), so they expose nothing new.

create or replace function public.is_class_teacher(p_class_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id and c.teacher_id = auth.uid()
  );
$$;

create or replace function public.is_class_member(p_class_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.class_members cm
    where cm.class_id = p_class_id and cm.student_id = auth.uid()
  );
$$;

-- True when the caller teaches a class that p_student_id belongs to.
create or replace function public.teaches_student(p_student_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.class_members cm
    join public.classes c on c.id = cm.class_id
    where cm.student_id = p_student_id and c.teacher_id = auth.uid()
  );
$$;

revoke all on function public.is_class_teacher(uuid) from public;
revoke all on function public.is_class_member(uuid) from public;
revoke all on function public.teaches_student(uuid) from public;
grant execute on function public.is_class_teacher(uuid) to authenticated;
grant execute on function public.is_class_member(uuid) to authenticated;
grant execute on function public.teaches_student(uuid) to authenticated;

drop policy if exists "Members can view their class" on public.classes;
create policy "Members can view their class"
  on public.classes for select
  using (public.is_class_member(id));

drop policy if exists "Teachers view own class roster" on public.class_members;
create policy "Teachers view own class roster"
  on public.class_members for select
  using (public.is_class_teacher(class_id));

drop policy if exists "Teachers manage own class assignments" on public.assignments;
create policy "Teachers manage own class assignments"
  on public.assignments for all
  using (public.is_class_teacher(class_id))
  with check (public.is_class_teacher(class_id));

drop policy if exists "Members can view class assignments" on public.assignments;
create policy "Members can view class assignments"
  on public.assignments for select
  using (public.is_class_member(class_id));

-- ============================================================
-- 0016_lesson_completions.sql
-- ============================================================
-- Normalized, server-timestamped lesson completions: the source of truth for
-- cohort activation, week-N activity and retention (docs/gtm/metric-glossary.md).
--
-- Rows are written ONLY by a trigger on public.progress, never by clients:
-- useProgress upserts the progress row straight from the browser, so hooking
-- the API route would miss almost every real completion. The trigger diffs
-- the `completed` array and stamps each newly seen lesson with the database
-- clock, so a client can't choose its own completed_at.
--
-- Completions that already exist when this runs are recorded with a NULL
-- completed_at ("before tracking began") rather than an invented timestamp.
-- Metrics must ignore NULL rows. Because the primary key already holds them,
-- a later re-sync of the same lesson can't give them a fake "now" either.
--
-- Known limitation: a learner who completes lessons signed-out and signs in
-- later is stamped at sync time. Acceptable for free pilots, where students
-- join signed-in; revisit before any credential depends on these timestamps.

create table if not exists public.lesson_completions (
  user_id      uuid not null references auth.users (id) on delete cascade,
  lesson_id    text not null check (char_length(lesson_id) between 1 and 64),
  completed_at timestamptz,
  primary key (user_id, lesson_id)
);

create index if not exists lesson_completions_completed_at_idx
  on public.lesson_completions (completed_at);

alter table public.lesson_completions enable row level security;

drop policy if exists "Users read own lesson completions" on public.lesson_completions;
create policy "Users read own lesson completions"
  on public.lesson_completions for select
  using (auth.uid() = user_id);

-- A teacher can read completions for students in a class they own. (Server
-- routes use the admin client after verifying ownership; this policy keeps
-- session-bound reads possible without widening anything else.) Uses the
-- recursion-safe helper from 0015.
drop policy if exists "Teachers read class member completions" on public.lesson_completions;
create policy "Teachers read class member completions"
  on public.lesson_completions for select
  using (public.teaches_student(user_id));

-- No insert/update/delete policies: only the trigger below writes rows.

create or replace function public.record_lesson_completions()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.lesson_completions (user_id, lesson_id, completed_at)
  select new.user_id, ids.lesson_id, now()
  from (
    select distinct value as lesson_id
    from jsonb_array_elements_text(
      case when jsonb_typeof(new.completed) = 'array' then new.completed else '[]'::jsonb end
    )
  ) ids
  where char_length(ids.lesson_id) between 1 and 64
    and (
      tg_op = 'INSERT'
      or not coalesce(old.completed, '[]'::jsonb) ? ids.lesson_id
    )
  on conflict (user_id, lesson_id) do nothing;
  return new;
end;
$$;

revoke all on function public.record_lesson_completions() from public;

drop trigger if exists progress_record_lesson_completions on public.progress;
create trigger progress_record_lesson_completions
  after insert or update of completed on public.progress
  for each row execute function public.record_lesson_completions();

-- Existing completions: recorded, but with no timestamp (see header).
insert into public.lesson_completions (user_id, lesson_id, completed_at)
select p.user_id, ids.lesson_id, null
from public.progress p
cross join lateral (
  select distinct value as lesson_id
  from jsonb_array_elements_text(
    case when jsonb_typeof(p.completed) = 'array' then p.completed else '[]'::jsonb end
  )
) ids
where char_length(ids.lesson_id) between 1 and 64
on conflict (user_id, lesson_id) do nothing;

-- ============================================================
-- 0017_cohort_skip_weeks.sql
-- ============================================================
-- Holiday skip weeks for cohorts (master plan A7). A skipped week is a
-- break: nothing is due, and it doesn't count as a cohort week for
-- activation or retention. The app computes the schedule from
-- (starts_on, skip_weeks) in src/lib/cohorts/template.ts; this stores the
-- skip list next to starts_on so metrics can rebuild the same week windows.

alter table public.classes
  add column if not exists skip_weeks date[] not null default '{}';

alter table public.classes
  drop constraint if exists classes_skip_weeks_check;
alter table public.classes
  add constraint classes_skip_weeks_check check (cardinality(skip_weeks) <= 3);

-- Replace the 5-argument launch function with one that also takes the skip
-- list. The old signature is dropped so PostgREST never has to choose
-- between overloads.
drop function if exists public.launch_cohort(uuid, text, date, text, jsonb);

create or replace function public.launch_cohort(
  p_class_id uuid,
  p_template_id text,
  p_starts_on date,
  p_timezone text,
  p_schedule jsonb,
  p_skip_weeks date[] default '{}'
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.classes c
    where c.id = p_class_id and c.teacher_id = auth.uid()
  ) then
    raise exception 'class_not_found' using errcode = 'P0002';
  end if;

  if p_template_id <> 'quant-foundations-v1' then
    raise exception 'unknown_template' using errcode = '22023';
  end if;

  if p_starts_on is null or nullif(btrim(p_timezone), '') is null then
    raise exception 'invalid_cohort_metadata' using errcode = '22023';
  end if;

  if coalesce(cardinality(p_skip_weeks), 0) > 3
     or exists (select 1 from unnest(p_skip_weeks) d where d <= p_starts_on) then
    raise exception 'invalid_skip_weeks' using errcode = '22023';
  end if;

  if jsonb_typeof(p_schedule) <> 'array' or jsonb_array_length(p_schedule) = 0 then
    raise exception 'invalid_schedule' using errcode = '22023';
  end if;

  update public.classes
  set template_id = p_template_id,
      starts_on = p_starts_on,
      timezone = p_timezone,
      skip_weeks = coalesce(p_skip_weeks, '{}'),
      launched_at = now()
  where id = p_class_id and teacher_id = auth.uid();

  insert into public.assignments (
    class_id,
    lesson_id,
    week_number,
    position,
    due_on
  )
  select
    p_class_id,
    item.lesson_id,
    item.week_number,
    item.position,
    item.due_on
  from jsonb_to_recordset(p_schedule) as item(
    lesson_id text,
    week_number smallint,
    position smallint,
    due_on date
  )
  on conflict (class_id, lesson_id) do update
  set week_number = excluded.week_number,
      position = excluded.position,
      due_on = excluded.due_on;
end;
$$;

revoke all on function public.launch_cohort(uuid, text, date, text, jsonb, date[]) from public;
grant execute on function public.launch_cohort(uuid, text, date, text, jsonb, date[]) to authenticated;

-- ============================================================
-- 0018_lesson_submissions.sql
-- ============================================================
-- Exercise code synced across devices (master plan A2). A student who
-- starts Black-Scholes on a school Chromebook can finish it at home.
-- One row per learner per lesson: the latest code, when it was saved, and
-- when it last passed the lesson's tests.
--
-- The client writes this directly (RLS: own rows only) and treats failures
-- as "saved on this device only", so the app works before this runs.

create table if not exists public.lesson_submissions (
  user_id        uuid not null references auth.users (id) on delete cascade,
  lesson_id      text not null check (char_length(lesson_id) between 1 and 64),
  code           text not null check (char_length(code) <= 50000),
  updated_at     timestamptz not null default now(),
  last_passed_at timestamptz,
  primary key (user_id, lesson_id)
);

alter table public.lesson_submissions enable row level security;

drop policy if exists "Users read own submissions" on public.lesson_submissions;
create policy "Users read own submissions"
  on public.lesson_submissions for select
  using (auth.uid() = user_id);

drop policy if exists "Users insert own submissions" on public.lesson_submissions;
create policy "Users insert own submissions"
  on public.lesson_submissions for insert
  with check (auth.uid() = user_id);

drop policy if exists "Users update own submissions" on public.lesson_submissions;
create policy "Users update own submissions"
  on public.lesson_submissions for update
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- A teacher can read the code of students in their classes, for the
-- "open a student's work when educationally necessary" flow. Read-only.
drop policy if exists "Teachers read class member submissions" on public.lesson_submissions;
create policy "Teachers read class member submissions"
  on public.lesson_submissions for select
  using (public.teaches_student(user_id));

-- ============================================================
-- 0019_capstone_submissions.sql
-- ============================================================
-- Private-by-default capstone (master plan A5): the week-6 artifact a
-- student can show. One per student per cohort class.
--
-- Access model:
--   * the student reads and edits their own row (RLS);
--   * a teacher opens a student's capstone only through
--     open_capstone_as_teacher(), which checks ownership of the class and
--     writes an access-log row, so viewing is a deliberate, recorded act;
--   * public sharing is opt-in: set_capstone_sharing() mints an unguessable
--     token (the client can never choose or keep one), and turning sharing
--     off deletes it, so the old link stops working immediately;
--   * the share page reads through get_shared_capstone(), which returns the
--     work only, never the student's name or id.

create table if not exists public.capstone_submissions (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  class_id        uuid not null references public.classes (id) on delete cascade,
  prompt_id       text not null check (prompt_id in ('option-pricing', 'backtest', 'open')),
  title           text not null default '' check (char_length(title) <= 120),
  thesis          text not null default '' check (char_length(thesis) <= 2000),
  code            text not null default '' check (char_length(code) <= 50000),
  result_summary  text not null default '' check (char_length(result_summary) <= 4000),
  reflection      text not null default '' check (char_length(reflection) <= 4000),
  status          text not null default 'draft' check (status in ('draft', 'submitted')),
  share_token     uuid unique,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  submitted_at    timestamptz,
  unique (user_id, class_id)
);

create index if not exists capstone_submissions_class_idx on public.capstone_submissions (class_id);

alter table public.capstone_submissions enable row level security;

drop policy if exists "Students read own capstone" on public.capstone_submissions;
create policy "Students read own capstone"
  on public.capstone_submissions for select
  using (auth.uid() = user_id);

-- A student may only start a capstone for a class they belong to.
drop policy if exists "Students create own capstone" on public.capstone_submissions;
create policy "Students create own capstone"
  on public.capstone_submissions for insert
  with check (auth.uid() = user_id and public.is_class_member(class_id));

drop policy if exists "Students edit own capstone" on public.capstone_submissions;
create policy "Students edit own capstone"
  on public.capstone_submissions for update
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

drop policy if exists "Students delete own capstone" on public.capstone_submissions;
create policy "Students delete own capstone"
  on public.capstone_submissions for delete
  using (auth.uid() = user_id);

-- Clients may write the content columns only. share_token, submitted_at,
-- ids and timestamps are set by the functions/trigger below.
revoke insert, update on public.capstone_submissions from anon, authenticated;
grant insert (user_id, class_id, prompt_id, title, thesis, code, result_summary, reflection, status)
  on public.capstone_submissions to authenticated;
grant update (prompt_id, title, thesis, code, result_summary, reflection, status)
  on public.capstone_submissions to authenticated;

-- updated_at on every write; submitted_at the first time status becomes
-- 'submitted' (kept on later edits so on-time submission is stable).
create or replace function public.capstone_stamp()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at := now();
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.submitted_at is null) then
    new.submitted_at := now();
  elsif tg_op = 'UPDATE' then
    new.submitted_at := old.submitted_at;
  end if;
  if tg_op = 'UPDATE' then
    new.share_token := case when current_setting('capstone.sharing', true) = 'on' then new.share_token else old.share_token end;
  else
    new.share_token := null;
  end if;
  return new;
end;
$$;

drop trigger if exists capstone_stamp on public.capstone_submissions;
create trigger capstone_stamp
  before insert or update on public.capstone_submissions
  for each row execute function public.capstone_stamp();

-- Turn public sharing on (new random token) or off (token deleted).
create or replace function public.set_capstone_sharing(p_capstone_id uuid, p_enabled boolean)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_token uuid;
  v_rows integer;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  perform set_config('capstone.sharing', 'on', true);
  update public.capstone_submissions
  set share_token = case when p_enabled then gen_random_uuid() else null end
  where id = p_capstone_id and user_id = auth.uid()
  returning share_token into v_token;
  get diagnostics v_rows = row_count;
  perform set_config('capstone.sharing', 'off', true);
  if v_rows = 0 then
    raise exception 'capstone_not_found' using errcode = 'P0002';
  end if;
  return v_token;
end;
$$;

-- The public share view: the work only, no name or ids.
create or replace function public.get_shared_capstone(p_token uuid)
returns table (
  prompt_id text,
  title text,
  thesis text,
  code text,
  result_summary text,
  reflection text,
  submitted_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select c.prompt_id, c.title, c.thesis, c.code, c.result_summary, c.reflection, c.submitted_at
  from public.capstone_submissions c
  where p_token is not null and c.share_token = p_token;
$$;

create table if not exists public.capstone_access_log (
  id           bigint generated always as identity primary key,
  capstone_id  uuid not null references public.capstone_submissions (id) on delete cascade,
  viewer_id    uuid not null references auth.users (id) on delete cascade,
  viewed_at    timestamptz not null default now()
);

alter table public.capstone_access_log enable row level security;

-- Students can see who opened their capstone and when.
drop policy if exists "Students read access to own capstone" on public.capstone_access_log;
create policy "Students read access to own capstone"
  on public.capstone_access_log for select
  using (
    exists (
      select 1 from public.capstone_submissions c
      where c.id = capstone_access_log.capstone_id and c.user_id = auth.uid()
    )
  );

-- A teacher opens one student's capstone; every open is logged.
create or replace function public.open_capstone_as_teacher(p_capstone_id uuid)
returns setof public.capstone_submissions
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.capstone_submissions c
    join public.classes k on k.id = c.class_id
    where c.id = p_capstone_id and k.teacher_id = auth.uid()
  ) then
    raise exception 'capstone_not_found' using errcode = 'P0002';
  end if;
  insert into public.capstone_access_log (capstone_id, viewer_id) values (p_capstone_id, auth.uid());
  return query select * from public.capstone_submissions where id = p_capstone_id;
end;
$$;

revoke all on function public.set_capstone_sharing(uuid, boolean) from public;
revoke all on function public.get_shared_capstone(uuid) from public;
revoke all on function public.open_capstone_as_teacher(uuid) from public;
grant execute on function public.set_capstone_sharing(uuid, boolean) to authenticated;
grant execute on function public.get_shared_capstone(uuid) to anon, authenticated;
grant execute on function public.open_capstone_as_teacher(uuid) to authenticated;

-- ============================================================
-- 0020_subscription_event_ordering.sql
-- ============================================================
-- Stripe doesn't guarantee webhook delivery order (money-paths audit,
-- Sprint 1.2). Record the `created` time of the event that last wrote each
-- subscription row, so an older customer.subscription.updated arriving late
-- can't overwrite newer status/plan. The webhook updates with
-- `where last_event_created is null or last_event_created <= <event.created>`
-- in the same statement, so the check and the write are atomic.

alter table public.subscriptions
  add column if not exists last_event_created bigint;

-- ============================================================
-- 0021_rate_limits.sql
-- ============================================================
-- Per-user rate limits for write endpoints (master plan D11): joining a
-- class by code (guessing codes), creating/launching classes, capstone
-- saves and sharing, and account deletion. One row per user per bucket
-- with a fixed window; consume_rate_limit() checks and counts in one
-- statement, so concurrent requests can't both slip under the limit
-- (same pattern as consume_ai_quota in 0008).

create table if not exists public.rate_limits (
  user_id      uuid not null references auth.users (id) on delete cascade,
  bucket       text not null check (char_length(bucket) between 1 and 64),
  window_start timestamptz not null default now(),
  count        integer not null default 0,
  primary key (user_id, bucket)
);

alter table public.rate_limits enable row level security;
-- No policies: only consume_rate_limit() touches this table.

create or replace function public.consume_rate_limit(p_bucket text, p_limit integer, p_window_seconds integer)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  insert into public.rate_limits as r (user_id, bucket, window_start, count)
  values (auth.uid(), p_bucket, now(), 1)
  on conflict (user_id, bucket) do update
    set window_start = case when r.window_start <= now() - make_interval(secs => p_window_seconds) then now() else r.window_start end,
        count = case when r.window_start <= now() - make_interval(secs => p_window_seconds) then 1 else r.count + 1 end
  returning r.count into v_count;
  return v_count <= p_limit;
end;
$$;

revoke all on function public.consume_rate_limit(text, integer, integer) from public;
grant execute on function public.consume_rate_limit(text, integer, integer) to authenticated;

-- ============================================================
-- 0022_private_challenge_leaderboard.sql
-- ============================================================
-- Challenge completions stop being public (work plan 2026-09-29, AG8).
--
-- 0003 gave challenge_completions a `using (true)` select policy, so anyone
-- holding the public anon key could list every row: user ids plus the name a
-- student typed at sign-up. /challenges then showed those names to signed-out
-- visitors. That contradicts what the homepage, /clubs and the pilot packet
-- promise ("no public profiles or leaderboards for students"), and it's the
-- wrong default for 13-18 year olds.
--
-- Now: students read only their own rows, and the leaderboard comes from
-- challenge_leaderboard(), which returns rank, time and XP, plus whether the
-- row is the caller's, and never a name or an id. The copied names are
-- removed; nothing reads them any more.

drop policy if exists "Completions publicly viewable" on public.challenge_completions;
drop policy if exists "Users read own completions" on public.challenge_completions;
create policy "Users read own completions"
  on public.challenge_completions for select
  using (auth.uid() = user_id);

update public.challenge_completions set display_name = null where display_name is not null;

create or replace function public.challenge_leaderboard(p_challenge_id text, p_limit integer default 10)
returns table (rank integer, elapsed_seconds integer, xp integer, is_you boolean)
language sql
stable
security definer
set search_path = public
as $$
  select r.rank, r.elapsed_seconds, r.xp, r.is_you
  from (
    select (row_number() over (order by c.elapsed_seconds, c.completed_at))::integer as rank,
           c.elapsed_seconds,
           c.xp,
           coalesce(c.user_id = auth.uid(), false) as is_you
    from public.challenge_completions c
    where c.challenge_id = p_challenge_id
  ) r
  -- The top N for everyone, plus the caller's own row wherever it ranks.
  where r.rank <= least(greatest(p_limit, 1), 50) or r.is_you
  order by r.rank;
$$;

revoke all on function public.challenge_leaderboard(text, integer) from public;
grant execute on function public.challenge_leaderboard(text, integer) to anon, authenticated;

-- ============================================================
-- 0023_class_ai_tutor.sql
-- ============================================================
-- Per-class switch for the AI tutor (build plan T3.5).
--
-- The tutor sends a student's question and code to a third-party model. A
-- club leader or school should decide whether their students can use it, so
-- the default for any class is OFF; the leader turns it on from the class
-- page. Independent students (in no class) are unaffected.
--
-- ai_tutor_allowed() answers for the signed-in user: false when they belong
-- to ANY class whose leader has not enabled the tutor (the most protective
-- reading when someone is in several classes). Existing classes start OFF.

alter table public.classes
  add column if not exists ai_tutor_enabled boolean not null default false;

create or replace function public.ai_tutor_allowed()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not exists (
    select 1
    from public.class_members m
    join public.classes c on c.id = m.class_id
    where m.student_id = auth.uid()
      and not c.ai_tutor_enabled
  );
$$;

revoke all on function public.ai_tutor_allowed() from public;
grant execute on function public.ai_tutor_allowed() to authenticated;

-- ============================================================
-- 0024_seasons.sql
-- ============================================================
-- Seasons (proving-ground spec, 2026-10-16): public handles, seasons of timed
-- challenges, per-student attempts, leaderboards from official scores, and
-- the intensive waitlist.
--
-- Every write to attempts goes through start_attempt()/submit_attempt(), and
-- every cross-user read through season_leaderboard(), so row-level security
-- stays closed: students read only their own attempts and nobody can set a
-- score. Official scores are written by the service role (scoring arrives in
-- a later migration/route).

-- ─── Handles ─────────────────────────────────────────────────────────────────
alter table public.profiles add column if not exists handle text;
alter table public.profiles drop constraint if exists profiles_handle_format;
alter table public.profiles
  add constraint profiles_handle_format check (handle is null or handle ~ '^[a-z0-9_]{3,20}$');
create unique index if not exists profiles_handle_unique_idx on public.profiles (lower(handle));

-- ─── Seasons and challenge slots (public schedule) ───────────────────────────
create table if not exists public.seasons (
  id         text primary key check (id ~ '^[a-z0-9-]{2,40}$'),
  title      text not null check (char_length(title) between 1 and 80),
  starts_on  date not null,
  ends_on    date not null,
  created_at timestamptz not null default now(),
  check (ends_on >= starts_on)
);
alter table public.seasons enable row level security;
drop policy if exists "Seasons are public" on public.seasons;
create policy "Seasons are public" on public.seasons for select using (true);

create table if not exists public.season_challenges (
  id                 text primary key check (id ~ '^[a-z0-9-]{2,60}$'),
  season_id          text not null references public.seasons (id) on delete cascade,
  week               smallint not null check (week between 1 and 8),
  template_slug      text not null check (char_length(template_slug) between 1 and 60),
  opens_at           timestamptz not null,
  closes_at          timestamptz not null,
  time_limit_minutes integer not null default 60 check (time_limit_minutes between 5 and 240),
  unique (season_id, week),
  check (closes_at > opens_at)
);
alter table public.season_challenges enable row level security;
drop policy if exists "Season challenges are public" on public.season_challenges;
create policy "Season challenges are public" on public.season_challenges for select using (true);

-- ─── Attempts (student work) ─────────────────────────────────────────────────
create table if not exists public.season_attempts (
  user_id        uuid not null references auth.users (id) on delete cascade,
  challenge_id   text not null references public.season_challenges (id) on delete cascade,
  started_at     timestamptz not null default now(),
  deadline       timestamptz not null,
  submitted_at   timestamptz,
  code           text check (char_length(code) <= 50000),
  explanation    text check (char_length(explanation) <= 2000),
  preview_passed boolean,
  official_score numeric check (official_score is null or (official_score >= 0 and official_score <= 100)),
  status         text not null default 'started'
                 check (status in ('started', 'submitted', 'scored', 'pending_review')),
  primary key (user_id, challenge_id)
);
alter table public.season_attempts enable row level security;
drop policy if exists "Students read own attempts" on public.season_attempts;
create policy "Students read own attempts"
  on public.season_attempts for select
  using (auth.uid() = user_id);
-- No insert/update/delete policies: the RPCs below are the only writers.

-- Start (or resume) an attempt. The clock starts once, on the server.
create or replace function public.start_attempt(p_challenge_id text)
returns table (started_at timestamptz, deadline timestamptz, status text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_ch  public.season_challenges%rowtype;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  select * into v_ch from public.season_challenges c where c.id = p_challenge_id;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.season_attempts a where a.user_id = v_uid and a.challenge_id = p_challenge_id) then
    if now() < v_ch.opens_at or now() >= v_ch.closes_at then
      raise exception 'not_open' using errcode = '22023';
    end if;
    insert into public.season_attempts (user_id, challenge_id, started_at, deadline)
    values (v_uid, p_challenge_id, now(),
            least(now() + make_interval(mins => v_ch.time_limit_minutes), v_ch.closes_at));
  end if;
  return query
    select a.started_at, a.deadline, a.status
    from public.season_attempts a
    where a.user_id = v_uid and a.challenge_id = p_challenge_id;
end;
$$;
revoke all on function public.start_attempt(text) from public;
grant execute on function public.start_attempt(text) to authenticated;

-- Submit once, before the deadline (30 seconds of grace for the network).
create or replace function public.submit_attempt(
  p_challenge_id text,
  p_code text,
  p_explanation text,
  p_preview_passed boolean
)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_at  public.season_attempts%rowtype;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  select * into v_at from public.season_attempts a
  where a.user_id = v_uid and a.challenge_id = p_challenge_id
  for update;
  if not found then
    raise exception 'not_started' using errcode = 'P0002';
  end if;
  if v_at.status <> 'started' then
    raise exception 'already_submitted' using errcode = '22023';
  end if;
  if now() > v_at.deadline + interval '30 seconds' then
    raise exception 'too_late' using errcode = '22023';
  end if;
  update public.season_attempts
  set code = p_code,
      explanation = p_explanation,
      preview_passed = p_preview_passed,
      submitted_at = now(),
      status = 'submitted'
  where user_id = v_uid and challenge_id = p_challenge_id;
  return now();
end;
$$;
revoke all on function public.submit_attempt(text, text, text, boolean) from public;
grant execute on function public.submit_attempt(text, text, text, boolean) to authenticated;

-- Leaderboard from official scores only. Handles, never names. A chapter
-- board (p_class_id) is visible only to that class's members and teacher.
create or replace function public.season_leaderboard(p_season_id text, p_class_id uuid default null)
returns table (rank integer, handle text, total_score numeric, solved integer, is_you boolean)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if p_class_id is not null and not (
    exists (select 1 from public.class_members m where m.class_id = p_class_id and m.student_id = auth.uid())
    or exists (select 1 from public.classes c where c.id = p_class_id and c.teacher_id = auth.uid())
  ) then
    return;
  end if;
  return query
    with totals as (
      select a.user_id, sum(a.official_score) as total, count(*)::integer as n
      from public.season_attempts a
      join public.season_challenges c on c.id = a.challenge_id
      where c.season_id = p_season_id
        and a.status = 'scored'
        and a.official_score is not null
        and (p_class_id is null or exists (
          select 1 from public.class_members m where m.class_id = p_class_id and m.student_id = a.user_id))
      group by a.user_id
    )
    select (rank() over (order by t.total desc, t.n desc))::integer,
           p.handle, t.total, t.n, (t.user_id = auth.uid())
    from totals t
    join public.profiles p on p.id = t.user_id
    where p.handle is not null
    order by 1, p.handle
    limit 100;
end;
$$;
revoke all on function public.season_leaderboard(text, uuid) from public;
grant execute on function public.season_leaderboard(text, uuid) to anon, authenticated;

-- No AI help while a timed attempt is running (extends 0023).
create or replace function public.ai_tutor_allowed()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not exists (
    select 1
    from public.class_members m
    join public.classes c on c.id = m.class_id
    where m.student_id = auth.uid()
      and not c.ai_tutor_enabled
  )
  and not exists (
    select 1
    from public.season_attempts a
    where a.user_id = auth.uid()
      and a.status = 'started'
      and now() < a.deadline
  );
$$;
revoke all on function public.ai_tutor_allowed() from public;
grant execute on function public.ai_tutor_allowed() to authenticated;

-- ─── Intensive waitlist (parents; service role only) ─────────────────────────
create table if not exists public.intensive_waitlist (
  id            uuid primary key default gen_random_uuid(),
  parent_email  text not null check (char_length(parent_email) between 3 and 254
                                     and parent_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  student_grade smallint check (student_grade between 6 and 12),
  note          text check (char_length(note) <= 1000),
  source        text check (char_length(source) <= 64),
  created_at    timestamptz not null default now()
);
create unique index if not exists intensive_waitlist_email_idx on public.intensive_waitlist (lower(parent_email));
alter table public.intensive_waitlist enable row level security;
-- No policies: only the server (service role) reads or writes it.
